from collections.abc import Callable

import pytest


def wrapped(job: Callable[[], str]) -> str:
    """Call job once and return 'start:' + its result + ':end'.

    The helper performs no I/O and no logging; it only calls job.
    """
    return "start:" + job() + ":end"


def test_wraps_result() -> None:
    assert wrapped(lambda: "x") == "start:x:end"


def test_wraps_empty_result() -> None:
    assert wrapped(lambda: "") == "start::end"


def test_calls_job_exactly_once() -> None:
    calls: list[int] = []

    def job() -> str:
        calls.append(1)
        return "ok"

    assert wrapped(job) == "start:ok:end"
    assert len(calls) == 1


def test_propagates_job_exception() -> None:
    def job() -> str:
        raise ValueError("boom")

    with pytest.raises(ValueError, match="boom"):
        wrapped(job)
